func TestSearch_NoTypeSearchesLocalFTS(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	db, err := store.Open(dbPath)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	if err := db.Upsert("commerce", "product_1", json.RawMessage(`{"id":"product_1","name":"matching cafe table"}`)); err != nil {
		t.Fatalf("upsert match: %v", err)
	}
	if err := db.Upsert("contacts", "contact_1", json.RawMessage(`{"id":"contact_1","name":"unrelated record"}`)); err != nil {
		t.Fatalf("upsert nonmatch: %v", err)
	}
	db.Close()

	var flags rootFlags
	cmd := newSearchCmd(&flags)
	var out bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&bytes.Buffer{})
	cmd.SetArgs([]string{"cafe", "--db", dbPath})

	if err := cmd.Execute(); err != nil {
		t.Fatalf("search execute: %v", err)
	}

	got := out.String()
	if !strings.Contains(got, "matching cafe table") {
		t.Fatalf("search output = %s, want synced local FTS result", got)
	}
	if strings.Contains(got, "unrelated record") {
		t.Fatalf("search output = %s, did not expect unrelated row", got)
	}
}
